with with_prev as (select *, lag(txn_time) over (partition by txn_type order by txn_time, id) as prev_txn_time from transactions), flagged as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval 30 days then 1 else 0 end as new_group_flag from with_prev) select id, account_id, txn_type, amount, txn_time, sum(new_group_flag) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged;
